package main

import (
	"image"
	"image/color"
	"image/png"
	"os"
)

func main() {
	// 1. Grayscale gradient 100x100
	img1 := image.NewRGBA(image.Rect(0, 0, 100, 100))
	for y := 0; y < 100; y++ {
		for x := 0; x < 100; x++ {
			v := uint8((x + y) * 255 / 198)
			img1.Set(x, y, color.RGBA{v, v, v, 255})
		}
	}
	f1, _ := os.Create("/tmp/gradient100.png")
	png.Encode(f1, img1)
	f1.Close()

	// 2. 10x10 gradient
	img2 := image.NewRGBA(image.Rect(0, 0, 10, 10))
	for y := 0; y < 10; y++ {
		for x := 0; x < 10; x++ {
			v := uint8((x + y) * 255 / 18)
			img2.Set(x, y, color.RGBA{v, v, v, 255})
		}
	}
	f2, _ := os.Create("/tmp/gradient10.png")
	png.Encode(f2, img2)
	f2.Close()

	// 3. 4x4 colors
	img3 := image.NewRGBA(image.Rect(0, 0, 4, 4))
	img3.Set(0, 0, color.RGBA{255, 0, 0, 255})
	img3.Set(1, 0, color.RGBA{0, 255, 0, 255})
	img3.Set(0, 1, color.RGBA{0, 0, 255, 255})
	img3.Set(1, 1, color.RGBA{255, 255, 255, 255})
	f3, _ := os.Create("/tmp/colors4.png")
	png.Encode(f3, img3)
	f3.Close()
}
EOF
go run /tmp/gen_imgs.go"}

