{"command":"cat <<'EOF' > /tmp/test_formula.go
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"os"
	"os/exec"
	"strings"
)

func testRGB(r, g, b uint8) string {
	img := image.NewRGBA(image.Rect(0, 0, 1, 1))
	img.Set(0, 0, color.RGBA{r, g, b, 255})
	f, _ := os.Create("/tmp/pixel.png")
	png.Encode(f, img)
	f.Close()

	// Use map of 256 chars or test with digits
	chars := ""
	for i := 0; i < 256; i++ {
		chars += fmt.Sprintf("%c", rune(33+i%90)) // distinguishable
	}
	// Better yet, pass a map where each character index is encoded
	// Let's test with a map of length 256!
	var map256 []byte
	for i := 0; i < 256; i++ {
		map256 = append(map256, byte('A'+(i%26)))
	}
	out, _ := exec.Command("./executable", "/tmp/pixel.png", "-d", "1,1", "-m", string(map256)).Output()
	return strings.TrimSpace(string(out))
}

func testRGBWithMap(r, g, b uint8, mapStr string) string {
	img := image.NewRGBA(image.Rect(0, 0, 1, 1))
	img.Set(0, 0, color.RGBA{r, g, b, 255})
	f, _ := os.Create("/tmp/pixel.png")
	png.Encode(f, img)
	f.Close()

	out, _ := exec.Command("./executable", "/tmp/pixel.png", "-d", "1,1", "-m", mapStr).Output()
	return strings.TrimSpace(string(out))
}

func main() {
	// Let's test standard grayscale formula on various colors:
	// R=100, G=0, B=0
	// R=0, G=100, B=0
	// R=0, G=0, B=100
	// R=100, G=100, B=100
	// R=100, G=0, B=200
	colors := [][3]uint8{
		{100, 0, 0},
		{0, 100, 0},
		{0, 0, 100},
		{100, 100, 100},
		{100, 0, 200},
		{255, 0, 0},
		{0, 255, 0},
		{0, 0, 255},
		{128, 64, 32},
	}

	// Create map of length 256 distinct characters (e.g. byte values or hex)
	// Wait, map in -m is a string. If length of map is N, pixel value V in 0..255 maps to index floor(V * N / 256) or floor(V * (N-1) / 255) or similar.
	// Let's test with N=256 distinct runes!
	runes := make([]rune, 256)
	for i := 0; i < 256; i++ {
		runes[i] = rune(0x1000 + i) // Unicode characters
	}
	map256 := string(runes)

	for _, c := range colors {
		out := testRGBWithMap(c[0], c[1], c[2], map256)
		if len([]rune(out)) > 0 {
			rVal := []rune(out)[0] - 0x1000
			fmt.Printf("RGB(%3d,%3d,%3d) -> mapped index: %d\n", c[0], c[1], c[2], rVal)
		}
	}
}
EOF
go run /tmp/test_formula.go"}

