{"command":"cat <<'EOF' > /tmp/test_details.go
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"os"
	"os/exec"
	"strings"
)

func getIndex(r, g, b, a uint8) int {
	img := image.NewRGBA(image.Rect(0, 0, 1, 1))
	img.Set(0, 0, color.NRGBA{r, g, b, a})
	f, _ := os.Create("/tmp/pixel.png")
	png.Encode(f, img)
	f.Close()

	runes := make([]rune, 256)
	for i := 0; i < 256; i++ {
		runes[i] = rune(0x1000 + i)
	}
	map256 := string(runes)

	out, _ := exec.Command("./executable", "/tmp/pixel.png", "-d", "1,1", "-m", map256).Output()
	s := strings.TrimSpace(string(out))
	if len([]rune(s)) == 0 {
		return -1
	}
	return int([]rune(s)[0] - 0x1000)
}

func main() {
	for i := 0; i <= 255; i += 32 {
		fmt.Printf("Gray(%3d) -> %d\n", i, getIndex(uint8(i), uint8(i), uint8(i), 255))
	}
	fmt.Println("--- R ---")
	for i := 0; i <= 255; i += 32 {
		fmt.Printf("R(%3d) -> %d\n", i, getIndex(uint8(i), 0, 0, 255))
	}
	fmt.Println("--- G ---")
	for i := 0; i <= 255; i += 32 {
		fmt.Printf("G(%3d) -> %d\n", i, getIndex(0, uint8(i), 0, 255))
	}
	fmt.Println("--- B ---")
	for i := 0; i <= 255; i += 32 {
		fmt.Printf("B(%3d) -> %d\n", i, getIndex(0, 0, uint8(i), 255))
	}
}
EOF
go run /tmp/test_details.go"}

