package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"os"
	"os/exec"
)

func getChar(r, g, b, a uint8, customMap string) string {
	img := image.NewRGBA(image.Rect(0, 0, 1, 1))
	img.Set(0, 0, color.NRGBA{r, g, b, a})
	f, _ := os.Create("/tmp/pixel.png")
	png.Encode(f, img)
	f.Close()

	out, _ := exec.Command("./executable", "/tmp/pixel.png", "-d", "1,1", "-m", customMap).Output()
	// Strip trailing newline only (\n or \r\n)
	s := string(out)
	if len(s) > 0 && s[len(s)-1] == '\n' {
		s = s[:len(s)-1]
	}
	if len(s) > 0 && s[len(s)-1] == '\r' {
		s = s[:len(s)-1]
	}
	return s
}

func main() {
	// Let's test with a map of 10 digits "0123456789"
	m := "0123456789"
	for _, v := range []uint8{0, 25, 51, 76, 102, 128, 153, 178, 204, 230, 255} {
		fmt.Printf("Gray(%3d) -> char: %q\n", v, getChar(v, v, v, 255, m))
