package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"math"
	"os"
	"os/exec"
	"strings"
)

func getChar(r, g, b uint8, m string) string {
	img := image.NewRGBA(image.Rect(0, 0, 1, 1))
	img.Set(0, 0, color.RGBA{r, g, b, 255})
	f, _ := os.Create("/tmp/pixel.png")
	png.Encode(f, img)
	f.Close()

	out, _ := exec.Command("./executable", "/tmp/pixel.png", "-d", "1,1", "-m", m).Output()
	return strings.TrimRight(string(out), "\r\n")
}

func main() {
	// Let's create a map of length 256 printable ASCII characters or byte values
	// If map length is 256: idx = int(val * 256 / 255). If idx >= 256 { idx = 255 }
	// So val = idx * 255 / 256 !
	// Let's test with a map of length 256 distinct runes/chars
	// Map with 256 chars: byte 0..255. But some bytes are non-printable.
	// What if map length is 100?
	// With map length 100: idx = int(val * 100 / 255).

	m100 := ""
	for i := 0; i < 100; i++ {
		m100 += string(rune(33 + i)) // printable ASCII chars
	}

	testRGB := [][3]uint8{
		{255, 0, 0},
		{0, 255, 0},
		{0, 0, 255},
		{100, 200, 50},
		{200, 100, 50},
		{50, 100, 200},
		{123, 45, 67},
		{200, 200, 200},
	}

	for _, c := range testRGB {
		r, g, b := c[0], c[1], c[2]
		ch := getChar(r, g, b, m100)
		var actualIdx int
		for i, runeVal := range m100 {
			if string(runeVal) == ch {
				actualIdx = i
				break
			}
		}

		v1 := 0.3*float64(r) + 0.59*float64(g) + 0.11*float64(b)
		v2 := 0.299*float64(r) + 0.587*float64(g) + 0.114*float64(b)
		v3 := 0.2126*float64(r) + 0.7152*float64(g) + 0.0722*float64(b)
		v4 := (float64(r) + float64(g) + float64(b)) / 3.0

		fmt.Printf("RGB(%3d,%3d,%3d) -> actual_idx=%2d\n", r, g, b, actualIdx)
		fmt.Printf("  0.3*R+0.59*G+0.11*B    = %.2f -> idx=%d\n", v1, int(v1*100/255))
		fmt.Printf("  0.299*R+0.587*G+0.114*B = %.2f -> idx=%d\n", v2, int(v2*100/255))
		fmt.Printf("  0.2126*R+0.7152*G+...  = %.2f -> idx=%d\n", v3, int(v3*100/255))
		fmt.Printf("  (R+G+B)/3              = %.2f -> idx=%d\n", v4, int(v4*100/255))
		_ = math.Abs
	}
}
