func main() {
	// Create a 2x4 image where each pixel is either 0 or 255
	// Let's test which dot corresponds to which pixel in 2x4 grid
	for y := 0; y < 4; y++ {
		for x := 0; x < 2; x++ {
			img := image.NewRGBA(image.Rect(0, 0, 2, 4))
			// Set all to 0
			for iy := 0; iy < 4; iy++ {
				for ix := 0; ix < 2; ix++ {
					img.Set(ix, iy, color.RGBA{0, 0, 0, 255})
				}
			}
			// Set pixel (x, y) to 255
			img.Set(x, y, color.RGBA{255, 255, 255, 255})
			f, _ := os.Create("/tmp/braille_pixel.png")
			png.Encode(f, img)
			f.Close()

			out, _ := exec.Command("./executable", "/tmp/braille_pixel.png", "-d", "1,1", "-b", "--threshold", "128").Output()
			s := strings.TrimRight(string(out), "\r\n")
			r := []rune(s)[0]
			bitmask := int(r - 0x2800)
			fmt.Printf("Pixel (x=%d, y=%d) -> Rune: U+%04X (bitmask 0x%02X)\n", x, y, r, bitmask)
		}
	}
}
