{"command":"cat <<'EOF' > /tmp/test_resize_alg.go
package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"os"
	"os/exec"
	"strings"

	"golang.org/x/image/draw"
)

func getActualResizedColors(imgPath string, w, h int) [][][3]uint8 {
	env := append(os.Environ(), "TERM=xterm-256color", "COLORTERM=truecolor")
	cmd := exec.Command("./executable", imgPath, "-d", fmt.Sprintf("%d,%d", w, h), "-C")
	cmd.Env = env
	out, _ := cmd.Output()
	s := string(out)

	lines := strings.Split(s, "\n")
	var result [][][3]uint8
	for _, l := range lines {
		l = strings.TrimSpace(l)
		if l == "" {
			continue
		}
		// Parse \x1b[38;2;r;g;bm<char>\x1b[0m
		var row [][3]uint8
		parts := strings.Split(l, "\x1b[0m")
		for _, p := range parts {
			if strings.Contains(p, "\x1b[38;2;") {
				idx := strings.Index(p, "\x1b[38;2;")
				sub := p[idx+7:]
				mIdx := strings.Index(sub, "m")
				if mIdx != -1 {
