package main

import (
	"fmt"
	"image/png"
	"os"
	"os/exec"
)

func main() {
	exec.Command("./executable", "/tmp/colors4.png", "-s", "/tmp", "-d", "4,4", "--font-color", "255,0,0", "--only-save").Run()
	f, _ := os.Open("/tmp/colors4-ascii-art.png")
	img, _ := png.Decode(f)
	f.Close()

	// Check center pixels to find non-black pixel
	b := img.Bounds()
	found := false
	for y := 0; y < b.Dy(); y++ {
		for x := 0; x < b.Dx(); x++ {
			r, g, b, _ := img.At(x, y).RGBA()
			r8, g8, b8 := r>>8, g>>8, b>>8
			if r8 > 200 && g8 < 50 && b8 < 50 {
				fmt.Printf("Found font pixel at (%d,%d): RGB(%d,%d,%d)\n", x, y, r8, g8, b8)
				found = true
				break
			}
		}
		if found {
			break
		}
	}
}
EOF
go run /tmp/check_font_color.go"}

