package main

import (
	"encoding/binary"
	"fmt"
	"image"
	"image/color"
	"image/png"
	"math"
	"os"
)

type Point struct {
	X, Y float64
	OnCurve bool
}

type TTFFont struct {
	data      []byte
	unitsPerEm uint16
	ascent    int16
	descent   int16
	cmap      map[rune]uint16
	locaFormat int16 // 0 for short, 1 for long
	locaOffset uint32
	glyfOffset uint32
}

func parseTTF(data []byte) (*TTFFont, error) {
	if len(data) < 12 {
		return nil, fmt.Errorf("invalid ttf")
	}
	numTables := binary.BigEndian.Uint16(data[4:6])
	tables := make(map[string]uint32)
	for i := 0; i < int(numTables); i++ {
		off := 12 + i*16
		tag := string(data[off : off+4])
		tableOff := binary.BigEndian.Uint32(data[off+8 : off+12])
		tables[tag] = tableOff
	}

	font := &TTFFont{data: data, cmap: make(map[rune]uint16)}

	// Parse head
	if headOff, ok := tables["head"]; ok {
		font.unitsPerEm = binary.BigEndian.Uint16(data[headOff+18 : headOff+20])
		font.locaFormat = int16(binary.BigEndian.Uint16(data[headOff+50 : headOff+52]))
	}
	font.locaOffset = tables["loca"]
	font.glyfOffset = tables["glyf"]

	// Parse hhea
	if hheaOff, ok := tables["hhea"]; ok {
		font.ascent = int16(binary.BigEndian.Uint16(data[hheaOff+4 : hheaOff+6]))
		font.descent = int16(binary.BigEndian.Uint16(data[hheaOff+6 : hheaOff+8]))
	}

	// Parse cmap
	if cmapOff, ok := tables["cmap"]; ok {
		numSubtables := binary.BigEndian.Uint16(data[cmapOff+2 : cmapOff+4])
		for i := 0; i < int(numSubtables); i++ {
			subOff := cmapOff + binary.BigEndian.Uint32(data[cmapOff+8+uint32(i)*8 : cmapOff+12+uint32(i)*8])
			format := binary.BigEndian.Uint16(data[subOff : subOff+2])
			if format == 4 {
				segCount := binary.BigEndian.Uint16(data[subOff+6:subOff+8]) / 2
				endCodes := subOff + 14
				startCodes := endCodes + uint32(segCount)*2 + 2
				idDelta := startCodes + uint32(segCount)*2
				idRangeOffset := idDelta + uint32(segCount)*2

				for s := 0; s < int(segCount)-1; s++ {
					end := binary.BigEndian.Uint16(data[endCodes+uint32(s)*2:])
					start := binary.BigEndian.Uint16(data[startCodes+uint32(s)*2:])
					delta := int16(binary.BigEndian.Uint16(data[idDelta+uint32(s)*2:]))
					ro := binary.BigEndian.Uint16(data[idRangeOffset+uint32(s)*2:])

					for r := start; r <= end; r++ {
						var glyphID uint16
						if ro == 0 {
							glyphID = uint16(int32(r) + int32(delta))
						} else {
							offset := idRangeOffset + uint32(s)*2 + uint32(ro) + uint32(r-start)*2
							if offset+2 <= uint32(len(data)) {
								g := binary.BigEndian.Uint16(data[offset:])
								if g != 0 {
									glyphID = uint16(int32(g) + int32(delta))
								}
							}
						}
						font.cmap[rune(r)] = glyphID
					}
				}
				break
			}
		}
	}

	return font, nil
}

func (f *TTFFont) getGlyphOffset(glyphID uint16) (uint32, uint32) {
	if f.locaFormat == 0 {
		off1 := uint32(binary.BigEndian.Uint16(f.data[f.locaOffset+uint32(glyphID)*2:])) * 2
		off2 := uint32(binary.BigEndian.Uint16(f.data[f.locaOffset+uint32(glyphID+1)*2:])) * 2
		return f.glyfOffset + off1, off2 - off1
	} else {
		off1 := binary.BigEndian.Uint32(f.data[f.locaOffset+uint32(glyphID)*4:])
		off2 := binary.BigEndian.Uint32(f.data[f.locaOffset+uint32(glyphID+1)*4:])
		return f.glyfOffset + off1, off2 - off1
	}
}

func main() {
	data, _ := os.ReadFile("/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf")
	font, err := parseTTF(data)
	if err != nil {
		fmt.Println("err:", err)
		return
	}
	fmt.Printf("Parsed font: unitsPerEm=%d, ascent=%d, descent=%d, cmap size=%d\n",
		font.unitsPerEm, font.ascent, font.descent, len(font.cmap))

	gID := font.cmap['A']
	off, length := font.getGlyphOffset(gID)
	fmt.Printf("Glyph 'A' ID=%d, offset=%d, len=%d\n", gID, off, length)
}
EOF
