package main

import (
	"encoding/binary"
	"fmt"
	"image"
	"image/color"
	"image/png"
	"math"
	"os"
)

type Point struct {
	X, Y    float64
	OnCurve bool
}

type Contour []Point

func parseGlyphContours(data []byte) ([]Contour, error) {
	if len(data) < 10 {
		return nil, nil
	}
	numContours := int16(binary.BigEndian.Uint16(data[0:2]))
	if numContours <= 0 {
		return nil, nil // compound glyphs or empty
	}

	endPts := make([]uint16, numContours)
	for i := 0; i < int(numContours); i++ {
		endPts[i] = binary.BigEndian.Uint16(data[10+i*2:])
	}
	numPoints := int(endPts[numContours-1]) + 1

	instrLen := binary.BigEndian.Uint16(data[10+numContours*2:])
	offset := 10 + numContours*2 + 2 + int(instrLen)

	// Read flags
	flags := make([]byte, numPoints)
	for i := 0; i < numPoints; {
		flag := data[offset]
		offset++
		flags[i] = flag
		i++
		if (flag & 8) != 0 { // repeat
			count := int(data[offset])
			offset++
			for r := 0; r < count && i < numPoints; r++ {
				flags[i] = flag
				i++
			}
		}
	}

	// Read X coordinates
	xCoords := make([]int16, numPoints)
	var x int16 = 0
	for i := 0; i < numPoints; i++ {
		flag := flags[i]
		if (flag & 2) != 0 { // short
			val := int16(data[offset])
			offset++
			if (flag & 16) == 0 {
				val = -val
			}
			x += val
		} else if (flag & 16) == 0 { // long
			val := int16(binary.BigEndian.Uint16(data[offset:]))
			offset += 2
			x += val
		}
		xCoords[i] = x
	}

	// Read Y coordinates
	yCoords := make([]int16, numPoints)
	var y int16 = 0
	for i := 0; i < numPoints; i++ {
		flag := flags[i]
		if (flag & 4) != 0 { // short
			val := int16(data[offset])
			offset++
			if (flag & 32) == 0 {
				val = -val
			}
			y += val
		} else if (flag & 32) == 0 { // long
			val := int16(binary.BigEndian.Uint16(data[offset:]))
			offset += 2
			y += val
		}
		yCoords[i] = y
	}

	// Assemble contours
	var contours []Contour
	start := 0
	for c := 0; c < int(numContours); c++ {
		end := int(endPts[c])
		var contour Contour
		for i := start; i <= end; i++ {
			contour = append(contour, Point{
				X:       float64(xCoords[i]),
				Y:       float64(yCoords[i]),
				OnCurve: (flags[i] & 1) != 0,
			})
		}
		contours = append(contours, contour)
		start = end + 1
	}

	return contours, nil
}

func rasterizeContours(contours []Contour, em int, scale float64, ox, oy int, target *image.RGBA, col color.RGBA) {
	// De-bezier curves into line segments
	var lines [][2]Point
	for _, c := range contours {
		if len(c) == 0 {
			continue
		}
		// Expand contour into points
		var pts []Point
		n := len(c)
		for i := 0; i < n; i++ {
			p1 := c[i]
			p2 := c[(i+1)%n]
			if p1.OnCurve && p2.OnCurve {
				pts = append(pts, p1)
			} else if p1.OnCurve && !p2.OnCurve {
				pts = append(pts, p1)
				var p3 Point
				if p2.OnCurve {
					p3 = p2
				} else {
					p3 = c[(i+2)%n]
					if !p3.OnCurve {
						p3 = Point{X: (p2.X + p3.X) / 2, Y: (p2.Y + p3.Y) / 2, OnCurve: true}
					}
				}
				// Quadratic Bezier (p1, p2, p3)
				for t := 0.1; t < 1.0; t += 0.1 {
					bx := (1-t)*(1-t)*p1.X + 2*(1-t)*t*p2.X + t*t*p3.X
					by := (1-t)*(1-t)*p1.Y + 2*(1-t)*t*p2.Y + t*t*p3.Y
					pts = append(pts, Point{X: bx, Y: by, OnCurve: true})
				}
			}
		}
		for i := 0; i < len(pts); i++ {
			p1 := pts[i]
			p2 := pts[(i+1)%len(pts)]
			// Transform coordinates
			x1 := float64(ox) + p1.X*scale
			y1 := float64(oy) - p1.Y*scale
			x2 := float64(ox) + p2.X*scale
			y2 := float64(oy) - p2.Y*scale
			lines = append(lines, [2]Point{{X: x1, Y: y1}, {X: x2, Y: y2}})
		}
	}

	// Scanline filling
	b := target.Bounds()
	minY, maxY := b.Min.Y, b.Max.Y
	minX, maxX := b.Min.X, b.Max.X

	for y := minY; y < maxY; y++ {
		fy := float64(y) + 0.5
		var intersections []float64
		for _, l := range lines {
			y1, y2 := l[0].Y, l[1].Y
			if (y1 <= fy && y2 > fy) || (y2 <= fy && y1 > fy) {
				x := l[0].X + (fy-y1)*(l[1].X-l[0].X)/(y2-y1)
				intersections = append(intersections, x)
			}
		}
		// Sort intersections
		for i := 0; i < len(intersections); i++ {
			for j := i + 1; j < len(intersections); j++ {
				if intersections[i] > intersections[j] {
					intersections[i], intersections[j] = intersections[j], intersections[i]
				}
			}
		}
		// Fill spans
		for i := 0; i+1 < len(intersections); i += 2 {
			xStart := int(math.Max(float64(minX), math.Ceil(intersections[i]-0.5)))
			xEnd := int(math.Min(float64(maxX-1), math.Floor(intersections[i+1]-0.5)))
			for x := xStart; x <= xEnd; x++ {
				target.SetRGBA(x, y, col)
			}
		}
	}
}

func main() {
	ttfData, _ := os.ReadFile("/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf")
	font, _ := parseTTF(ttfData)
	gID := font.cmap['@']
	off, lenG := font.getGlyphOffset(gID)

	contours, err := parseGlyphContours(ttfData[off : off+lenG])
	fmt.Printf("Contours count: %d, err: %v\n", len(contours), err)

	img := image.NewRGBA(image.Rect(0, 0, 14, 28))
	// Fill background black
	for y := 0; y < 28; y++ {
		for x := 0; x < 14; x++ {
			img.Set(x, y, color.RGBA{0, 0, 0, 255})
		}
	}

	scale := 24.0 / float64(font.unitsPerEm)
	rasterizeContours(contours, int(font.unitsPerEm), scale, 1, 22, img, color.RGBA{255, 255, 255, 255})

	f, _ := os.Create("/tmp/rendered_at.png")
	png.Encode(f, img)
	f.Close()
	fmt.Println("Saved /tmp/rendered_at.png")
}
