	for _, c := range contours {
		if len(c) == 0 {
			continue
		}
		var pts []Point
		n := len(c)
		for i := 0; i < n; i++ {
			p1 := c[i]
			p2 := c[(i+1)%n]
			if p1.OnCurve && p2.OnCurve {
				pts = append(pts, p1)
			} else if p1.OnCurve && !p2.OnCurve {
				pts = append(pts, p1)
				var p3 Point
				if p2.OnCurve {
					p3 = p2
				} else {
					p3 = c[(i+2)%n]
					if !p3.OnCurve {
