	minY, maxY := b.Min.Y, b.Max.Y
	minX, maxX := b.Min.X, b.Max.X

	for y := minY; y < maxY; y++ {
		fy := float64(y) + 0.5
		var intersections []float64
		for _, l := range lines {
			y1, y2 := l[0].Y, l[1].Y
			if (y1 <= fy && y2 > fy) || (y2 <= fy && y1 > fy) {
				x := l[0].X + (fy-y1)*(l[1].X-l[0].X)/(y2-y1)
				intersections = append(intersections, x)
			}
		}
		for i := 0; i < len(intersections); i++ {
			for j := i + 1; j < len(intersections); j++ {
				if intersections[i] > intersections[j] {
					intersections[i], intersections[j] = intersections[j], intersections[i]
				}
			}
		}
		for i := 0; i+1 < len(intersections); i += 2 {
			xStart := int(math.Max(float64(minX), math.Ceil(intersections[i]-0.5)))
			xEnd := int(math.Min(float64(maxX-1), math.Floor(intersections[i+1]-0.5)))
			for x := xStart; x <= xEnd; x++ {
				target.SetRGBA(x, y, col)
			}
		}
	}
}

func main() {
	ttfData, _ := os.ReadFile("/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf")
	font, _ := parseTTF(ttfData)
	gID := font.cmap['@']
	off, lenG := font.getGlyphOffset(gID)

	contours, err := parseGlyphContours(ttfData[off : off+lenG])
	fmt.Printf("Contours count: %d, err: %v\n", len(contours), err)

	img := image.NewRGBA(image.Rect(0, 0, 14, 28))
	for y := 0; y < 28; y++ {
		for x := 0; x < 14; x++ {
			img.Set(x, y, color.RGBA{0, 0, 0, 255})
		}
	}

	scale := 24.0 / float64(font.unitsPerEm)
	rasterizeContours(contours, int(font.unitsPerEm), scale, 1, 22, img, color.RGBA{255, 255, 255, 255})

	f, _ := os.Create("/tmp/rendered_at.png")
	png.Encode(f, img)
	f.Close()
	fmt.Println("Saved /tmp/rendered_at.png")
}
