			for iy := start; iy <= end; iy++ {
				dy := float64(iy) - center
				w := lanczos3(dy * math.Min(scaleY, 1.0))
				if w == 0 {
					continue
				}
				c := tmp.RGBAAt(x, iy)
				r += float64(c.R) * w
				g += float64(c.G) * w
				b += float64(c.B) * w
				a += float64(c.A) * w
				weightSum += w
			}
