package resize

import (
	"image"
	"image/color"
	"math"
)

func sinc(x float64) float64 {
	if x == 0 {
		return 1.0
	}
	x *= math.Pi
	return math.Sin(x) / x
}

func lanczos3(x float64) float64 {
	x = math.Abs(x)
	if x < 3.0 {
		return sinc(x) * sinc(x/3.0)
	}
	return 0.0
}

func Resize(dstW, dstH int, src image.Image) *image.RGBA {
	bounds := src.Bounds()
	srcW := bounds.Dx()
	srcH := bounds.Dy()

	if dstW <= 0 || dstH <= 0 || srcW <= 0 || srcH <= 0 {
		return image.NewRGBA(image.Rect(0, 0, 1, 1))
	}

	// First pass: horizontal
	tmp := image.NewRGBA(image.Rect(0, 0, dstW, srcH))
	scaleX := float64(dstW) / float64(srcW)
	radiusX := 3.0
	if scaleX < 1.0 {
		radiusX = 3.0 / scaleX
	}

	for y := 0; y < srcH; y++ {
		for x := 0; x < dstW; x++ {
			center := (float64(x)+0.5)/scaleX - 0.5
			start := int(math.Floor(center - radiusX))
			end := int(math.Ceil(center + radiusX))
			if start < bounds.Min.X {
				start = bounds.Min.X
			}
			if end >= bounds.Max.X {
				end = bounds.Max.X - 1
			}

			var r, g, b, a, weightSum float64
			for ix := start; ix <= end; ix++ {
				dx := float64(ix) - center
				w := lanczos3(dx * math.Min(scaleX, 1.0))
				if w == 0 {
					continue
				}
				c := src.At(ix+bounds.Min.X, y+bounds.Min.Y)
				cr, cg, cb, ca := c.RGBA()
				r += float64(cr>>8) * w
				g += float64(cg>>8) * w
				b += float64(cb>>8) * w
				a += float64(ca>>8) * w
				weightSum += w
			}
			if weightSum != 0 {
				r /= weightSum
				g /= weightSum
				b /= weightSum
				a /= weightSum
			}
			tmp.SetRGBA(x, y, color.RGBA{
				R: uint8(math.Min(math.Max(r, 0), 255)),
				G: uint8(math.Min(math.Max(g, 0), 255)),
				B: uint8(math.Min(math.Max(b, 0), 255)),
				A: uint8(math.Min(math.Max(a, 0), 255)),
			})
		}
	}

	// Second pass: vertical
	dst := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	scaleY := float64(dstH) / float64(srcH)
	radiusY := 3.0
	if scaleY < 1.0 {
		radiusY = 3.0 / scaleY
	}

	for x := 0; x < dstW; x++ {
		for y := 0; y < dstH; y++ {
			center := (float64(y)+0.5)/scaleY - 0.5
			start := int(math.Floor(center - radiusY))
			end := int(math.Ceil(center + radiusY))
			if start < 0 {
				start = 0
			}
			if end >= srcH {
				end = srcH - 1
			}

			var r, g, b, a, weightSum float64
			for iy := start; iy <= end; iy++ {
				dy := float64(iy) - center
				w := lanczos3(dy * math.Min(scaleY, 1.0))
				if w == 0 {
					continue
				}
				c := tmp.RGBAAt(x, iy)
				r += float64(c.R) * w
				g += float64(c.G) * w
				b += float64(c.B) * w
				a += float64(c.A) * w
				weightSum += w
			}
			if weightSum != 0 {
				r /= weightSum
				g /= weightSum
				b /= weightSum
				a /= weightSum
			}
			dst.SetRGBA(x, y, color.RGBA{
				R: uint8(math.Min(math.Max(r, 0), 255)),
				G: uint8(math.Min(math.Max(g, 0), 255)),
				B: uint8(math.Min(math.Max(b, 0), 255)),
				A: uint8(math.Min(math.Max(a, 0), 255)),
			})
		}
	}

	return dst
}
