{"command":"mkdir -p font
cat <<'EOF' > font/rasterizer.go
package font

import (
	_ "embed"
	"encoding/binary"
	"fmt"
	"image"
	"image/color"
	"math"
	"os"
)

//go:embed fonts/DejaVuSansMono.ttf
var defaultAsciiFontBytes []byte

//go:embed fonts/DejaVuSans.ttf
var defaultBrailleFontBytes []byte

type Point struct {
	X, Y    float64
	OnCurve bool
}

type Contour []Point

type TTFFont struct {
	data       []byte
	unitsPerEm uint16
	ascent     int16
	descent    int16
	cmap       map[rune]uint16
	locaFormat int16
	locaOffset uint32
	glyfOffset uint32
}

func LoadFont(path string, isBraille bool) (*TTFFont, error) {
	var data []byte
	var err error
	if path != "" {
		data, err = os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("unable to open font file: %v", err)
		}
	} else {
		if isBraille {
			data = defaultBrailleFontBytes
		} else {
			data = defaultAsciiFontBytes
		}
	}
	return ParseTTF(data)
}

func ParseTTF(data []byte) (*TTFFont, error) {
	if len(data) < 12 {
		return nil, fmt.Errorf("invalid ttf data")
	}
	numTables := binary.BigEndian.Uint16(data[4:6])
	tables := make(map[string]uint32)
	for i := 0; i < int(numTables); i++ {
		off := 12 + i*16
		tag := string(data[off : off+4])
		tableOff := binary.BigEndian.Uint32(data[off+8 : off+12])
		tables[tag] = tableOff
	}

	font := &TTFFont{data: data, cmap: make(map[rune]uint16)}

	if headOff, ok := tables["head"]; ok {
		font.unitsPerEm = binary.BigEndian.Uint16(data[headOff+18 : headOff+20])
		font.locaFormat = int16(binary.BigEndian.Uint16(data[headOff+50 : headOff+52]))
	}
	font.locaOffset = tables["loca"]
	font.glyfOffset = tables["glyf"]

	if hheaOff, ok := tables["hhea"]; ok {
		font.ascent = int16(binary.BigEndian.Uint16(data[hheaOff+4 : hheaOff+6]))
		font.descent = int16(binary.BigEndian.Uint16(data[hheaOff+6 : hheaOff+8]))
	}

	if cmapOff, ok := tables["cmap"]; ok {
		numSubtables := binary.BigEndian.Uint16(data[cmapOff+2 : cmapOff+4])
		for i := 0; i < int(numSubtables); i++ {
			subOff := cmapOff + binary.BigEndian.Uint32(data[cmapOff+8+uint32(i)*8 : cmapOff+12+uint32(i)*8])
			format := binary.BigEndian.Uint16(data[subOff : subOff+2])
			if format == 4 {
				segCount := binary.BigEndian.Uint16(data[subOff+6:subOff+8]) / 2
				endCodes := subOff + 14
				startCodes := endCodes + uint32(segCount)*2 + 2
				idDelta := startCodes + uint32(segCount)*2
				idRangeOffset := idDelta + uint32(segCount)*2

				for s := 0; s < int(segCount)-1; s++ {
					end := binary.BigEndian.Uint16(data[endCodes+uint32(s)*2:])
					start := binary.BigEndian.Uint16(data[startCodes+uint32(s)*2:])
					delta := int16(binary.BigEndian.Uint16(data[idDelta+uint32(s)*2:]))
					ro := binary.BigEndian.Uint16(data[idRangeOffset+uint32(s)*2:])

					for r := start; r <= end; r++ {
						var glyphID uint16
						if ro == 0 {
							glyphID = uint16(int32(r) + int32(delta))
						} else {
							offset := idRangeOffset + uint32(s)*2 + uint32(ro) + uint32(r-start)*2
							if offset+2 <= uint32(len(data)) {
								g := binary.BigEndian.Uint16(data[offset:])
								if g != 0 {
									glyphID = uint16(int32(g) + int32(delta))
								}
							}
						}
						font.cmap[rune(r)] = glyphID
					}
				}
				break
			}
		}
	}

	return font, nil
}

func (f *TTFFont) getGlyphOffset(glyphID uint16) (uint32, uint32) {
	if f.locaFormat == 0 {
		off1 := uint32(binary.BigEndian.Uint16(f.data[f.locaOffset+uint32(glyphID)*2:])) * 2
		off2 := uint32(binary.BigEndian.Uint16(f.data[f.locaOffset+uint32(glyphID+1)*2:])) * 2
		return f.glyfOffset + off1, off2 - off1
	} else {
		off1 := binary.BigEndian.Uint32(f.data[f.locaOffset+uint32(glyphID)*4:])
		off2 := binary.BigEndian.Uint32(f.data[f.locaOffset+uint32(glyphID+1)*4:])
		return f.glyfOffset + off1, off2 - off1
	}
}

func (f *TTFFont) parseGlyphContours(glyphID uint16) ([]Contour, error) {
	off, lenG := f.getGlyphOffset(glyphID)
	if lenG == 0 || off+lenG > uint32(len(f.data)) {
		return nil, nil
	}
	data := f.data[off : off+lenG]
	if len(data) < 10 {
		return nil, nil
	}
	numContours := int16(binary.BigEndian.Uint16(data[0:2]))
	if numContours <= 0 {
		return nil, nil
	}

	endPts := make([]uint16, numContours)
	for i := 0; i < int(numContours); i++ {
		endPts[i] = binary.BigEndian.Uint16(data[10+i*2:])
	}
	numPoints := int(endPts[numContours-1]) + 1

	instrLen := binary.BigEndian.Uint16(data[10+int(numContours)*2:])
	offset := 10 + int(numContours)*2 + 2 + int(instrLen)

	flags := make([]byte, numPoints)
	for i := 0; i < numPoints; {
		flag := data[offset]
		offset++
		flags[i] = flag
		i++
		if (flag & 8) != 0 {
			count := int(data[offset])
			offset++
			for r := 0; r < count && i < numPoints; r++ {
				flags[i] = flag
				i++
			}
		}
	}

	xCoords := make([]int16, numPoints)
	var x int16 = 0
	for i := 0; i < numPoints; i++ {
		flag := flags[i]
		if (flag & 2) != 0 {
			val := int16(data[offset])
			offset++
			if (flag & 16) == 0 {
				val = -val
			}
			x += val
		} else if (flag & 16) == 0 {
			val := int16(binary.BigEndian.Uint16(data[offset:]))
			offset += 2
			x += val
		}
		xCoords[i] = x
	}

	yCoords := make([]int16, numPoints)
	var y int16 = 0
	for i := 0; i < numPoints; i++ {
		flag := flags[i]
		if (flag & 4) != 0 {
			val := int16(data[offset])
			offset++
			if (flag & 32) == 0 {
				val = -val
			}
			y += val
		} else if (flag & 32) == 0 {
			val := int16(binary.BigEndian.Uint16(data[offset:]))
			offset += 2
			y += val
		}
		yCoords[i] = y
	}

	var contours []Contour
	start := 0
	for c := 0; c < int(numContours); c++ {
		end := int(endPts[c])
		var contour Contour
		for i := start; i <= end; i++ {
			contour = append(contour, Point{
				X:       float64(xCoords[i]),
				Y:       float64(yCoords[i]),
				OnCurve: (flags[i] & 1) != 0,
			})
		}
		contours = append(contours, contour)
		start = end + 1
	}

	return contours, nil
}

func (f *TTFFont) DrawRune(target *image.RGBA, r rune, cellX, cellY, cellW, cellH int, col color.RGBA) {
	if r == ' ' || r == '⠀' {
		return
	}
	gID, ok := f.cmap[r]
	if !ok {
		return
	}
	contours, err := f.parseGlyphContours(gID)
	if err != nil || len(contours) == 0 {
		return
	}

	scale := float64(cellH) * 0.8 / float64(f.unitsPerEm)
	ox := cellX + 1
	oy := cellY + int(float64(cellH)*0.78)

	var lines [][2]Point
	for _, c := range contours {
		if len(c) == 0 {
			continue
		}
		var pts []Point
		n := len(c)
		for i := 0; i < n; i++ {
			p1 := c[i]
			p2 := c[(i+1)%n]
			if p1.OnCurve && p2.OnCurve {
				pts = append(pts, p1)
			} else if p1.OnCurve && !p2.OnCurve {
				pts = append(pts, p1)
				var p3 Point
				if p2.OnCurve {
					p3 = p2
				} else {
					p3 = c[(i+2)%n]
					if !p3.OnCurve {
						p3 = Point{X: (p2.X + p3.X) / 2, Y: (p2.Y + p3.Y) / 2, OnCurve: true}
					}
				}
				for t := 0.1; t < 1.0; t += 0.1 {
					bx := (1-t)*(1-t)*p1.X + 2*(1-t)*t*p2.X + t*t*p3.X
					by := (1-t)*(1-t)*p1.Y + 2*(1-t)*t*p2.Y + t*t*p3.Y
					pts = append(pts, Point{X: bx, Y: by, OnCurve: true})
				}
			}
		}
		for i := 0; i < len(pts); i++ {
			p1 := pts[i]
			p2 := pts[(i+1)%len(pts)]
			x1 := float64(ox) + p1.X*scale
			y1 := float64(oy) - p1.Y*scale
			x2 := float64(ox) + p2.X*scale
			y2 := float64(oy) - p2.Y*scale
			lines = append(lines, [2]Point{{X: x1, Y: y1}, {X: x2, Y: y2}})
		}
	}

	minY := cellY
	maxY := cellY + cellH
	minX := cellX
	maxX := cellX + cellW

	for y := minY; y < maxY; y++ {
		fy := float64(y) + 0.5
		var intersections []float64
		for _, l := range lines {
			y1, y2 := l[0].Y, l[1].Y
			if (y1 <= fy && y2 > fy) || (y2 <= fy && y1 > fy) {
				x := l[0].X + (fy-y1)*(l[1].X-l[0].X)/(y2-y1)
				intersections = append(intersections, x)
			}
		}
		for i := 0; i < len(intersections); i++ {
			for j := i + 1; j < len(intersections); j++ {
				if intersections[i] > intersections[j] {
					intersections[i], intersections[j] = intersections[j], intersections[i]
				}
			}
		}
		for i := 0; i+1 < len(intersections); i += 2 {
			xStart := int(math.Max(float64(minX), math.Ceil(intersections[i]-0.5)))
			xEnd := int(math.Min(float64(maxX-1), math.Floor(intersections[i+1]-0.5)))
			for x := xStart; x <= xEnd; x++ {
				target.SetRGBA(x, y, col)
			}
		}
	}
}
EOF"}

