		reader = bytes.NewReader(data)
		parts := strings.Split(inputPath, "/")
		basename = parts[len(parts)-1]
		if idx := strings.Index(basename, "?"); idx != -1 {
			basename = basename[:idx]
		}
		if ext := filepath.Ext(basename); ext != "" {
			basename = strings.TrimSuffix(basename, ext)
		}
	} else if inputPath == "-" || inputPath == "/dev/stdin" {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return fmt.Errorf("unable to read stdin: %v", err)
		}
		reader = bytes.NewReader(data)
		basename = "stdin"
	} else {
		f, err := os.Open(inputPath)
		if err != nil {
			return fmt.Errorf("unable to open file: %v", err)
		}
		defer f.Close()
		data, err := io.ReadAll(f)
		if err != nil {
			return fmt.Errorf("unable to open file: %v", err)
		}
		reader = bytes.NewReader(data)
		base := filepath.Base(inputPath)
		ext := filepath.Ext(base)
		if ext != "" {
			basename = strings.TrimSuffix(base, ext)
		} else {
			basename = base
		}
	}

	srcImg, _, err := image.Decode(reader)
	if err != nil {
		return fmt.Errorf("can't decode %s: %v", inputPath, err)
	}

	bounds := srcImg.Bounds()
	imgW, imgH := bounds.Dx(), bounds.Dy()

	termW, termH, err := term.GetSize(int(os.Stdout.Fd()))
	if err != nil || termW <= 0 || termH <= 0 {
		termW = 80
		termH = 24
	}

	var width, height int
	if opts.Full {
		width = termW
		height = int(float64(termW) * 0.5 * float64(imgH) / float64(imgW))
	} else if len(opts.Dimensions) == 2 {
		width = opts.Dimensions[0]
		height = opts.Dimensions[1]
	} else if opts.Width > 0 {
		width = opts.Width
		height = int(float64(opts.Width) * 0.5 * float64(imgH) / float64(imgW))
	} else if opts.Height > 0 {
		height = opts.Height
		width = int(float64(opts.Height) * 2.0 * float64(imgW) / float64(imgH))
	} else {
		height = termH - 1
		if height <= 0 {
			height = 20
		}
		width = int(float64(height) * 2.0 * float64(imgW) / float64(imgH))
	}

	if width < 1 {
		width = 1
	}
	if height < 1 {
		height = 1
	}

	// Prepare map string
	mapStr := " .:-=+*#%@"
	if opts.Complex {
		mapStr = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"
	}
	if opts.Map != "" {
		mapStr = opts.Map
	}
	mapRunes := []rune(mapStr)

