				c := resized.RGBAAt(x, y)
				lum := 0.299*float64(c.R) + 0.587*float64(c.G) + 0.114*float64(c.B)
				if opts.Negative {
					lum = 255.0 - lum
				}
				grayGrid[y][x] = lum
			}
