					oldVal := grayGrid[y][x]
					newVal := 0.0
					if oldVal >= 128.0 {
						newVal = 255.0
					}
					grayGrid[y][x] = newVal
					err := oldVal - newVal

					if x+1 < rw {
						grayGrid[y][x+1] += err * 7.0 / 16.0
					}
					if y+1 < rh {
						if x-1 >= 0 {
							grayGrid[y+1][x-1] += err * 3.0 / 16.0
						}
						grayGrid[y+1][x] += err * 5.0 / 16.0
						if x+1 < rw {
							grayGrid[y+1][x+1] += err * 1.0 / 16.0
						}
					}
				}
			}
		}

