				var bitmask rune
				var sumR, sumG, sumB float64
				for dy := 0; dy < 4; dy++ {
					for dx := 0; dx < 2; dx++ {
						px := wx*2 + dx
						py := hy*4 + dy
						c := resized.RGBAAt(px, py)
						r, g, b := float64(c.R), float64(c.G), float64(c.B)
						if opts.Negative {
							r = 255 - r
							g = 255 - g
							b = 255 - b
						}
