	if scaleY > 1.0 {
		filterScaleY = 1.0 / scaleY
	}

	for x := 0; x < dstW; x++ {
		for y := 0; y < dstH; y++ {
			center := (float64(y)+0.5)*scaleY - 0.5
			start := int(math.Floor(center - 3.0/filterScaleY))
			end := int(math.Ceil(center + 3.0/filterScaleY))
			if start < 0 {
				start = 0
			}
			if end >= srcH {
				end = srcH - 1
			}

			var r, g, b, a, weightSum float64
			for iy := start; iy <= end; iy++ {
				dy := float64(iy) - center
				w := lanczos3(dy * filterScaleY)
				if w == 0 {
					continue
				}
				c := tmp.RGBAAt(x, iy)
				r += float64(c.R) * w
				g += float64(c.G) * w
				b += float64(c.B) * w
				a += float64(c.A) * w
				weightSum += w
			}
			if weightSum != 0 {
				r /= weightSum
				g /= weightSum
				b /= weightSum
				a /= weightSum
			}
