package main

import (
	"fmt"
	"image"
	"image/color"
	_ "image/png"
	"math"
	"os"
	"os/exec"
	"strings"
)

func sinc(x float64) float64 {
	if x == 0 { return 1 }
	x *= math.Pi
	return math.Sin(x) / x
}

func lanczos2(x float64) float64 {
	x = math.Abs(x)
	if x < 2 { return sinc(x) * sinc(x/2) }
	return 0
}

func bicubic(x float64) float64 {
	x = math.Abs(x)
	if x < 1 {
		return 1.5*x*x*x - 2.5*x*x + 1
	} else if x < 2 {
		return -0.5*x*x*x + 2.5*x*x - 4*x + 2
	}
	return 0
}

func mitchell(x float64) float64 {
	x = math.Abs(x)
	b, c := 1.0/3.0, 1.0/3.0
	if x < 1 {
		return ((12-9*b-6*c)*x*x*x + (-18+12*b+6*c)*x*x + (6-2*b)) / 6.0
	} else if x < 2 {
		return ((-b-6*c)*x*x*x + (6*b+30*c)*x*x + (-12*b-48*c)*x + (8*b+24*c)) / 6.0
	}
	return 0
}

func resizeFilter(dstW, dstH int, src image.Image, kernel func(float64) float64, radius float64) *image.RGBA {
	bounds := src.Bounds()
	srcW, srcH := bounds.Dx(), bounds.Dy()

	tmp := image.NewRGBA(image.Rect(0, 0, dstW, srcH))
	scaleX := float64(srcW) / float64(dstW)
	for y := 0; y < srcH; y++ {
		for x := 0; x < dstW; x++ {
			center := (float64(x)+0.5)*scaleX - 0.5
			start := int(math.Floor(center - radius))
			end := int(math.Ceil(center + radius))
			if start < 0 { start = 0 }
			if end >= srcW { end = srcW - 1 }
			var r, g, b, a, wSum float64
			for ix := start; ix <= end; ix++ {
				w := kernel((float64(ix) - center))
				if w == 0 { continue }
				cr, cg, cb, ca := src.At(ix, y).RGBA()
				r += float64(cr>>8) * w
				g += float64(cg>>8) * w
				b += float64(cb>>8) * w
				a += float64(ca>>8) * w
				wSum += w
			}
			if wSum != 0 { r /= wSum; g /= wSum; b /= wSum; a /= wSum }
			tmp.SetRGBA(x, y, color.RGBA{
				R: uint8(math.Min(math.Max(r, 0), 255)),
				G: uint8(math.Min(math.Max(g, 0), 255)),
				B: uint8(math.Min(math.Max(b, 0), 255)),
				A: uint8(math.Min(math.Max(a, 0), 255)),
			})
		}
	}

	dst := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	scaleY := float64(srcH) / float64(dstH)
	for x := 0; x < dstW; x++ {
		for y := 0; y < dstH; y++ {
			center := (float64(y)+0.5)*scaleY - 0.5
			start := int(math.Floor(center - radius))
			end := int(math.Ceil(center + radius))
			if start < 0 { start = 0 }
			if end >= srcH { end = srcH - 1 }
			var r, g, b, a, wSum float64
			for iy := start; iy <= end; iy++ {
				w := kernel((float64(iy) - center))
				if w == 0 { continue }
				c := tmp.RGBAAt(x, iy)
