{"command":"cat <<'EOF' > /tmp/test_dither_algs.go
package main

import (
	"fmt"
	"image"
	_ "image/png"
	"os"
	"os/exec"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/resize"
)

// Atkinson dithering
func ditherAtkinson(gray [][]float64) [][]float64 {
	rh := len(gray)
	rw := len(gray[0])
	out := make([][]float64, rh)
	for y := 0; y < rh; y++ {
		out[y] = make([]float64, rw)
		copy(out[y], gray[y])
	}
	for y := 0; y < rh; y++ {
		for x := 0; x < rw; x++ {
			oldV := out[y][x]
			newV := 0.0
			if oldV >= 128.0 {
				newV = 255.0
			}
			out[y][x] = newV
			err := (oldV - newV) / 8.0

			if x+1 < rw { out[y][x+1] += err }
			if x+2 < rw { out[y][x+2] += err }
			if y+1 < rh {
				if x-1 >= 0 { out[y+1][x-1] += err }
				out[y+1][x] += err
				if x+1 < rw { out[y+1][x+1] += err }
			}
			if y+2 < rh { out[y+2][x] += err }
		}
	}
	return out
}

func testResizedToBraille(gray [][]float64, width, height int) string {
	dotMap := [4][2]rune{
		{0x01, 0x08},
		{0x02, 0x10},
		{0x04, 0x20},
		{0x40, 0x80},
	}
	var sb strings.Builder
	for hy := 0; hy < height; hy++ {
		for wx := 0; wx < width; wx++ {
			var bitmask rune
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					px := wx*2 + dx
					py := hy*4 + dy
					if gray[py][px] >= 128.0 {
						bitmask |= dotMap[dy][dx]
					}
				}
			}
			sb.WriteRune(rune(0x2800 + bitmask))
		}
		sb.WriteString("\n")
	}
	return strings.TrimSpace(sb.String())
}

func main() {
	out, _ := exec.Command("./executable", "/tmp/gradient10.png", "-d", "10,10", "-b", "--dither").Output()
	orig := strings.TrimSpace(string(out))

	f, _ := os.Open("/tmp/gradient10.png")
	srcImg, _, _ := image.Decode(f)
	f.Close()

