			gridB[y][x] = float64(c.B)
		}
	}

	out := image.NewRGBA(image.Rect(0, 0, w, h))

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			oldR := math.Min(math.Max(gridR[y][x], 0), 255)
			oldG := math.Min(math.Max(gridG[y][x], 0), 255)
			oldB := math.Min(math.Max(gridB[y][x], 0), 255)

