	_ "image/png"
	"os"
	"os/exec"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/resize"
)

func ditherPalette(img *image.RGBA) *image.RGBA {
	bounds := img.Bounds()
	w, h := bounds.Dx(), bounds.Dy()

	gridR := make([][]float64, h)
	gridG := make([][]float64, h)
	gridB := make([][]float64, h)
	for y := 0; y < h; y++ {
		gridR[y] = make([]float64, w)
		gridG[y] = make([]float64, w)
		gridB[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			c := img.RGBAAt(x, y)
			gridR[y][x] = float64(c.R)
			gridG[y][x] = float64(c.G)
			gridB[y][x] = float64(c.B)
		}
	}

	out := image.NewRGBA(image.Rect(0, 0, w, h))

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			r := gridR[y][x]
			g := gridG[y][x]
			b := gridB[y][x]

			// Distance to 0,0,0 vs 255,255,255
			dist0 := r*r + g*g + b*b
			dist255 := (255-r)*(255-r) + (255-g)*(255-g) + (255-b)*(255-b)

			var targetVal float64
			if dist255 < dist0 {
				targetVal = 255.0
			} else {
				targetVal = 0.0
			}

			errR := r - targetVal
			errG := g - targetVal
			errB := b - targetVal

			if targetVal == 255.0 {
				out.SetRGBA(x, y, image.RGBA{}.ColorModel().Convert(image.NewRGBA(image.Rect(0,0,1,1)).RGBAAt(0,0)).(image.RGBA).RGBAAt(0,0))
			}
			_ = errR
			_ = errG
			_ = errB
		}
	}
	return out
}

func main() {
	out, _ := exec.Command("./executable", "/tmp/gradient10.png", "-d", "10,10", "-b", "--dither").Output()
	orig := strings.TrimSpace(string(out))
	fmt.Println("ORIGINAL:")
	fmt.Println(orig)

	_ = ditherPalette
}
