func dither16(img *image.RGBA) *image.RGBA {
	bounds := img.Bounds()
	w, h := bounds.Dx(), bounds.Dy()

	gridR := make([][]float64, h)
	gridG := make([][]float64, h)
	gridB := make([][]float64, h)
	for y := 0; y < h; y++ {
		gridR[y] = make([]float64, w)
		gridG[y] = make([]float64, w)
		gridB[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			c := img.RGBAAt(x, y)
			r, g, b, _ := c.RGBA()
			gridR[y][x] = float64(r)
			gridG[y][x] = float64(g)
			gridB[y][x] = float64(b)
		}
	}

	out := image.NewRGBA(image.Rect(0, 0, w, h))

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			r := math.Min(math.Max(gridR[y][x], 0), 65535)
			g := math.Min(math.Max(gridG[y][x], 0), 65535)
			b := math.Min(math.Max(gridB[y][x], 0), 65535)

			// Euclidean distance in uint16 space to Black (0) and White (65535)
			dBlack := r*r + g*g + b*b
			dR := 65535.0 - r
			dG := 65535.0 - g
			dB := 65535.0 - b
			dWhite := dR*dR + dG*dG + dB*dB

			var pVal float64
			var outCol color.RGBA
			if dWhite < dBlack {
				pVal = 65535.0
				outCol = color.RGBA{255, 255, 255, 255}
			} else {
				pVal = 0.0
				outCol = color.RGBA{0, 0, 0, 255}
			}

			out.SetRGBA(x, y, outCol)

			errR := r - pVal
			errG := g - pVal
			errB := b - pVal

			diffuse := func(nx, ny int, factor float64) {
				if nx >= 0 && nx < w && ny >= 0 && ny < h {
					gridR[ny][nx] += errR * factor
					gridG[ny][nx] += errG * factor
					gridB[ny][nx] += errB * factor
				}
			}

			diffuse(x+1, y, 7.0/16.0)
			diffuse(x-1, y+1, 3.0/16.0)
			diffuse(x, y+1, 5.0/16.0)
			diffuse(x+1, y+1, 1.0/16.0)
		}
	}

	return out
}

func testResizedToBraille(img *image.RGBA) string {
	width, height := img.Bounds().Dx()/2, img.Bounds().Dy()/4
	dotMap := [4][2]rune{
