package main

import (
	"fmt"
	"image"
	_ "image/png"
	"os"
	"os/exec"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/resize"
)

func dither16bitExact(img *image.RGBA) string {
	bounds := img.Bounds()
	w, h := bounds.Dx(), bounds.Dy()

	// 16-bit grayscale buffer
	gray := make([][]int32, h)
	for y := 0; y < h; y++ {
		gray[y] = make([]int32, w)
		for x := 0; x < w; x++ {
			c := img.RGBAAt(x, y)
			r, g, b, _ := c.RGBA() // 0..65535
			lum := (299*int32(r) + 587*int32(g) + 114*int32(b)) / 1000
			gray[y][x] = lum
		}
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			oldVal := gray[y][x]
			newVal := int32(0)
			if oldVal >= 32768 {
				newVal = 65535
			}
			gray[y][x] = newVal
			err := oldVal - newVal

			if x+1 < w {
				gray[y][x+1] += (err * 7) / 16
			}
			if y+1 < h {
				if x-1 >= 0 {
					gray[y+1][x-1] += (err * 3) / 16
				}
				gray[y+1][x] += (err * 5) / 16
				if x+1 < w {
					gray[y+1][x+1] += (err * 1) / 16
				}
			}
		}
	}

	dotMap := [4][2]rune{
		{0x01, 0x08},
		{0x02, 0x10},
		{0x04, 0x20},
		{0x40, 0x80},
	}
	var sb strings.Builder
	for hy := 0; hy < h/4; hy++ {
		for wx := 0; wx < w/2; wx++ {
			var bitmask rune
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					px := wx*2 + dx
					py := hy*4 + dy
					if gray[py][px] >= 32768 {
						bitmask |= dotMap[dy][dx]
					}
				}
			}
			sb.WriteRune(rune(0x2800 + bitmask))
		}
		sb.WriteString("\n")
	}
	return strings.TrimSpace(sb.String())
}

func main() {
	out, _ := exec.Command("./executable", "/tmp/gradient10.png", "-d", "10,10", "-b", "--dither").Output()
	orig := strings.TrimSpace(string(out))

	f, _ := os.Open("/tmp/gradient10.png")
	srcImg, _, _ := image.Decode(f)
	f.Close()

	img := resize.Resize(20, 40, srcImg)
	res := dither16bitExact(img)

	fmt.Println("Exact 16-bit Dither Match:", res == orig)
	if res == orig {
		fmt.Println("EXACT MATCH SUCCESSFUL!")
	} else {
		fmt.Println("ORIGINAL:")
		fmt.Println(orig)
		fmt.Println("REBUILT:")
		fmt.Println(res)
	}
