		for x := 0; x < w; x++ {
			oldVal := gray[y][x]
			newVal := int32(0)
			if oldVal >= 32768 {
				newVal = 65535
			}
			gray[y][x] = newVal
			err := oldVal - newVal

			if x+1 < w {
				gray[y][x+1] += (err * 7) / 16
			}
			if y+1 < h {
				if x-1 >= 0 {
					gray[y+1][x-1] += (err * 3) / 16
				}
				gray[y+1][x] += (err * 5) / 16
				if x+1 < w {
					gray[y+1][x+1] += (err * 1) / 16
				}
			}
		}
	}

	dotMap := [4][2]rune{
		{0x01, 0x08},
		{0x02, 0x10},
		{0x04, 0x20},
		{0x40, 0x80},
	}
