			bufR[y][x] = float64(r)
			bufG[y][x] = float64(g)
			bufB[y][x] = float64(b)
			bufA[y][x] = float64(a)
		}
	}

	out := image.NewRGBA(image.Rect(0, 0, w, h))

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			currR := math.Min(math.Max(bufR[y][x], 0), 65535)
			currG := math.Min(math.Max(bufG[y][x], 0), 65535)
			currB := math.Min(math.Max(bufB[y][x], 0), 65535)
			currA := math.Min(math.Max(bufA[y][x], 0), 65535)

			currCol := color.RGBA64{
				R: uint16(currR),
