			}

			nearest := palette.Convert(currCol)
			nR, nG, nB, nA := nearest.RGBA()

			out.Set(x, y, nearest)

			errR := currR - float64(nR)
			errG := currG - float64(nG)
			errB := currB - float64(nB)
			errA := currA - float64(nA)

