package main

import (
	"fmt"
	"image"
	_ "image/png"
	"math"
	"os"
	"os/exec"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/resize"
)

func sRGBToLinear(v float64) float64 {
	v /= 65535.0
	if v <= 0.04045 {
		return v / 12.92
	}
	return math.Pow((v+0.055)/1.055, 2.4)
}

func ditherPkgExact(img *image.RGBA) string {
	w, h := img.Bounds().Dx(), img.Bounds().Dy()

	gridR := make([][]float64, h)
	gridG := make([][]float64, h)
	gridB := make([][]float64, h)
	for y := 0; y < h; y++ {
		gridR[y] = make([]float64, w)
		gridG[y] = make([]float64, w)
		gridB[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			c := img.At(x, y)
			r, g, b, _ := c.RGBA()
			gridR[y][x] = sRGBToLinear(float64(r))
			gridG[y][x] = sRGBToLinear(float64(g))
			gridB[y][x] = sRGBToLinear(float64(b))
		}
	}

	ditheredBits := make([][]bool, h)
	for y := 0; y < h; y++ {
		ditheredBits[y] = make([]bool, w)
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			r := math.Min(math.Max(gridR[y][x], 0.0), 1.0)
			g := math.Min(math.Max(gridG[y][x], 0.0), 1.0)
			b := math.Min(math.Max(gridB[y][x], 0.0), 1.0)

			distBlack := r*r + g*g + b*b
			dR := 1.0 - r
			dG := 1.0 - g
			dB := 1.0 - b
			distWhite := dR*dR + dG*dG + dB*dB

			var target float64
			if distWhite < distBlack {
				target = 1.0
				ditheredBits[y][x] = true
			} else {
				target = 0.0
				ditheredBits[y][x] = false
			}

			errR := r - target
			errG := g - target
			errB := b - target

			diffuse := func(nx, ny int, factor float64) {
				if nx >= 0 && nx < w && ny >= 0 && ny < h {
					gridR[ny][nx] += errR * factor
					gridG[ny][nx] += errG * factor
					gridB[ny][nx] += errB * factor
				}
			}

			diffuse(x+1, y, 7.0/16.0)
			diffuse(x-1, y+1, 3.0/16.0)
			diffuse(x, y+1, 5.0/16.0)
			diffuse(x+1, y+1, 1.0/16.0)
		}
	}

	dotMap := [4][2]rune{
		{0x01, 0x08},
		{0x02, 0x10},
		{0x04, 0x20},
		{0x40, 0x80},
	}
	var sb strings.Builder
	for hy := 0; hy < h/4; hy++ {
		for wx := 0; wx < w/2; wx++ {
			var bitmask rune
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					px := wx*2 + dx
					py := hy*4 + dy
					if ditheredBits[py][px] {
						bitmask |= dotMap[dy][dx]
					}
				}
			}
			sb.WriteRune(rune(0x2800 + bitmask))
		}
		sb.WriteString("\n")
	}
	return strings.TrimSpace(sb.String())
}

func main() {
	out, _ := exec.Command("./executable", "/tmp/gradient10.png", "-d", "10,10", "-b", "--dither").Output()
	orig := strings.TrimSpace(string(out))

	f, _ := os.Open("/tmp/gradient10.png")
	srcImg, _, _ := image.Decode(f)
	f.Close()

	img := resize.Resize(20, 40, srcImg)
	res := ditherPkgExact(img)

	fmt.Println("Dither Exact Clamped Match:", res == orig)
	if res == orig {
		fmt.Println("EXACT 100% MATCH SUCCESSFUL!")
	} else {
		fmt.Println("ORIGINAL:")
		fmt.Println(orig)
		fmt.Println("REBUILT:")
		fmt.Println(res)
	}
}
EOF
