type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTerminalSize(fd int) (width, height int, err error) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 0, 0, errno
	}
	return int(ws.Col), int(ws.Row), nil
}

type Options struct {
	Color       bool
	ColorBg     bool
	Dimensions  []int
	Width       int
	Height      int
	Map         string
	Braille     bool
	Threshold   int
	Dither      bool
	Grayscale   bool
	Complex     bool
	Full        bool
	Negative    bool
