func ProcessImage(inputPath string, opts *Options) error {
	if opts.SaveTxtPath != "" {
		if _, err := os.Stat(opts.SaveTxtPath); err != nil {
			return fmt.Errorf("can't save file: stat %s/: no such file or directory", opts.SaveTxtPath)
		}
	}
	if opts.SaveImgPath != "" {
		if _, err := os.Stat(opts.SaveImgPath); err != nil {
			return fmt.Errorf("can't save file: stat %s/: no such file or directory", opts.SaveImgPath)
		}
		if _, err := font.LoadFont(opts.Font, opts.Braille); err != nil {
			return err
		}
	}

	var reader io.Reader
	var basename string

	if strings.HasPrefix(inputPath, "http://") || strings.HasPrefix(inputPath, "https://") {
		fmt.Print("Fetching file from url...")
		resp, err := http.Get(inputPath)
		if err != nil {
			fmt.Println()
			return fmt.Errorf("can't fetch content: %v", err)
		}
		defer resp.Body.Close()
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			fmt.Println()
			return fmt.Errorf("can't fetch content: %v", err)
		}
		fmt.Print("\r                          \r")
		reader = bytes.NewReader(data)
		parts := strings.Split(inputPath, "/")
		basename = parts[len(parts)-1]
		if idx := strings.Index(basename, "?"); idx != -1 {
			basename = basename[:idx]
		}
		if ext := filepath.Ext(basename); ext != "" {
			basename = strings.TrimSuffix(basename, ext)
		}
	} else if inputPath == "-" || inputPath == "/dev/stdin" {
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return fmt.Errorf("unable to read stdin: %v", err)
		}
		reader = bytes.NewReader(data)
		basename = "stdin"
	} else {
		f, err := os.Open(inputPath)
		if err != nil {
			return fmt.Errorf("unable to open file: %v", err)
		}
		defer f.Close()
		data, err := io.ReadAll(f)
		if err != nil {
			return fmt.Errorf("unable to open file: %v", err)
		}
		reader = bytes.NewReader(data)
		base := filepath.Base(inputPath)
		ext := filepath.Ext(base)
		if ext != "" {
			basename = strings.TrimSuffix(base, ext)
		} else {
			basename = base
		}
	}

	srcImg, _, err := image.Decode(reader)
	if err != nil {
		return fmt.Errorf("can't decode %s: %v", inputPath, err)
	}

	bounds := srcImg.Bounds()
	imgW, imgH := bounds.Dx(), bounds.Dy()

	termW, termH, err := getTerminalSize(int(os.Stdout.Fd()))
	if err != nil || termW <= 0 || termH <= 0 {
		termW = 80
		termH = 24
	}

	var width, height int
	if opts.Full {
		width = termW
		height = int(float64(termW) * 0.5 * float64(imgH) / float64(imgW))
	} else if len(opts.Dimensions) == 2 {
		width = opts.Dimensions[0]
		height = opts.Dimensions[1]
	} else if opts.Width > 0 {
		width = opts.Width
		height = int(float64(opts.Width) * 0.5 * float64(imgH) / float64(imgW))
	} else if opts.Height > 0 {
		height = opts.Height
		width = int(float64(opts.Height) * 2.0 * float64(imgW) / float64(imgH))
	} else {
		height = termH - 1
		if height <= 0 {
			height = 20
		}
		width = int(float64(height) * 2.0 * float64(imgW) / float64(imgH))
	}

	if width < 1 {
		width = 1
	}
	if height < 1 {
		height = 1
	}

	mapStr := " .:-=+*#%@"
	if opts.Complex {
		mapStr = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"
	}
	if opts.Map != "" {
		mapStr = opts.Map
	}
	mapRunes := []rune(mapStr)

	var resized *image.RGBA
	if opts.Braille {
		resized = resize.Resize(width*2, height*4, srcImg)
	} else {
		resized = resize.Resize(width, height, srcImg)
	}

	if opts.FlipX || opts.FlipY {
		rB := resized.Bounds()
		flipped := image.NewRGBA(rB)
		rw, rh := rB.Dx(), rB.Dy()
		for y := 0; y < rh; y++ {
			for x := 0; x < rw; x++ {
				srcX := x
				srcY := y
				if opts.FlipX {
					srcX = rw - 1 - x
				}
				if opts.FlipY {
					srcY = rh - 1 - y
				}
				flipped.SetRGBA(x, y, resized.RGBAAt(srcX, srcY))
			}
		}
		resized = flipped
	}

	colorSupport := checkColorSupport()
	warnColorSupport := false
	if opts.Color && colorSupport == 0 {
		warnColorSupport = true
	}

	charMatrix := make([][]rune, height)
	rgbMatrix := make([][][3]uint8, height)

	if opts.Braille {
		rw, rh := width*2, height*4
		ditheredBits := make([][]bool, rh)
		for y := 0; y < rh; y++ {
			ditheredBits[y] = make([]bool, rw)
		}

		if opts.Dither {
			gridR := make([][]float64, rh)
			gridG := make([][]float64, rh)
			gridB := make([][]float64, rh)
			for y := 0; y < rh; y++ {
				gridR[y] = make([]float64, rw)
				gridG[y] = make([]float64, rw)
				gridB[y] = make([]float64, rw)
				for x := 0; x < rw; x++ {
					c := resized.At(x, y)
					r, g, b, _ := c.RGBA()
					gridR[y][x] = sRGBToLinear(float64(r))
					gridG[y][x] = sRGBToLinear(float64(g))
					gridB[y][x] = sRGBToLinear(float64(b))
				}
			}

			for y := 0; y < rh; y++ {
				for x := 0; x < rw; x++ {
					r := gridR[y][x]
					g := gridG[y][x]
					b := gridB[y][x]

					distBlack := r*r + g*g + b*b
					dR := 1.0 - r
					dG := 1.0 - g
					dB := 1.0 - b
					distWhite := dR*dR + dG*dG + dB*dB

					var target float64
					if distWhite < distBlack {
						target = 1.0
						ditheredBits[y][x] = true
					} else {
						target = 0.0
						ditheredBits[y][x] = false
					}

					errR := r - target
					errG := g - target
					errB := b - target

					diffuse := func(nx, ny int, factor float64) {
						if nx >= 0 && nx < rw && ny >= 0 && ny < rh {
							gridR[ny][nx] += errR * factor
							gridG[ny][nx] += errG * factor
							gridB[ny][nx] += errB * factor
						}
					}

					diffuse(x+1, y, 7.0/16.0)
					diffuse(x-1, y+1, 3.0/16.0)
					diffuse(x, y+1, 5.0/16.0)
					diffuse(x+1, y+1, 1.0/16.0)
				}
			}
		}

		dotMap := [4][2]rune{
			{0x01, 0x08},
			{0x02, 0x10},
			{0x04, 0x20},
			{0x40, 0x80},
		}

		thresh := float64(opts.Threshold)

		for hy := 0; hy < height; hy++ {
			charMatrix[hy] = make([]rune, width)
			rgbMatrix[hy] = make([][3]uint8, width)
			for wx := 0; wx < width; wx++ {
				var bitmask rune
				var sumR, sumG, sumB float64
				for dy := 0; dy < 4; dy++ {
					for dx := 0; dx < 2; dx++ {
						px := wx*2 + dx
						py := hy*4 + dy
						c := resized.RGBAAt(px, py)
						r, g, b := float64(c.R), float64(c.G), float64(c.B)
						if opts.Negative {
							r = 255 - r
							g = 255 - g
							b = 255 - b
						}
						sumR += r
						sumG += g
						sumB += b

						if opts.Dither {
							if ditheredBits[py][px] {
								bitmask |= dotMap[dy][dx]
							}
						} else {
							lum := math.Round(0.299*r + 0.587*g + 0.114*b)
							if lum >= thresh {
								bitmask |= dotMap[dy][dx]
							}
						}
					}
				}
				charMatrix[hy][wx] = rune(0x2800 + bitmask)
				rgbMatrix[hy][wx] = [3]uint8{
					uint8(math.Min(math.Max(sumR/8.0, 0), 255)),
					uint8(math.Min(math.Max(sumG/8.0, 0), 255)),
					uint8(math.Min(math.Max(sumB/8.0, 0), 255)),
				}
			}
		}
	} else {
		for hy := 0; hy < height; hy++ {
			charMatrix[hy] = make([]rune, width)
			rgbMatrix[hy] = make([][3]uint8, width)
			for wx := 0; wx < width; wx++ {
				c := resized.RGBAAt(wx, hy)
				r, g, b := float64(c.R), float64(c.G), float64(c.B)
				lum := math.Round(0.299*r + 0.587*g + 0.114*b)
				if opts.Negative {
					lum = 255.0 - lum
					r = 255.0 - r
					g = 255.0 - g
					b = 255.0 - b
				}
				idx := int(lum * float64(len(mapRunes)) / 255.0)
				if idx >= len(mapRunes) {
					idx = len(mapRunes) - 1
				}
				if idx < 0 {
					idx = 0
				}
				charMatrix[hy][wx] = mapRunes[idx]
				rgbMatrix[hy][wx] = [3]uint8{
					uint8(math.Min(math.Max(r, 0), 255)),
					uint8(math.Min(math.Max(g, 0), 255)),
					uint8(math.Min(math.Max(b, 0), 255)),
				}
			}
		}
	}

	if !opts.OnlySave {
		if warnColorSupport {
			fmt.Print("Error: your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available\n\n")
		}
		var sb strings.Builder
		for y := 0; y < height; y++ {
			for x := 0; x < width; x++ {
				ch := string(charMatrix[y][x])
				r, g, b := rgbMatrix[y][x][0], rgbMatrix[y][x][1], rgbMatrix[y][x][2]
				lum := uint8(math.Round(0.299*float64(r) + 0.587*float64(g) + 0.114*float64(b)))

				if opts.Color && colorSupport > 0 {
					if colorSupport == 2 {
						if opts.ColorBg {
							sb.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm%s\x1b[0m", r, g, b, ch))
						} else {
							sb.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s\x1b[0m", r, g, b, ch))
						}
					} else {
						col8 := rgbTo8Bit(r, g, b)
						if opts.ColorBg {
							sb.WriteString(fmt.Sprintf("\x1b[48;5;%dm%s\x1b[0m", col8, ch))
						} else {
							sb.WriteString(fmt.Sprintf("\x1b[38;5;%dm%s\x1b[0m", col8, ch))
						}
					}
				} else if opts.Grayscale && colorSupport > 0 {
					if colorSupport == 2 {
						if opts.ColorBg {
							sb.WriteString(fmt.Sprintf("\x1b[48;2;%d;%d;%dm%s\x1b[0m", lum, lum, lum, ch))
						} else {
							sb.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s\x1b[0m", lum, lum, lum, ch))
						}
					} else {
						col8 := rgbTo8Bit(lum, lum, lum)
						if opts.ColorBg {
							sb.WriteString(fmt.Sprintf("\x1b[48;5;%dm%s\x1b[0m", col8, ch))
						} else {
							sb.WriteString(fmt.Sprintf("\x1b[38;5;%dm%s\x1b[0m", col8, ch))
						}
					}
				} else if opts.FontColor[0] != 255 || opts.FontColor[1] != 255 || opts.FontColor[2] != 255 {
					sb.WriteString(fmt.Sprintf("\x1b[38;2;%d;%d;%dm%s\x1b[0m", opts.FontColor[0], opts.FontColor[1], opts.FontColor[2], ch))
				} else {
					sb.WriteString(ch)
				}
			}
			sb.WriteString("\n")
		}
		fmt.Print(sb.String())
	}

	if opts.SaveTxtPath != "" {
		dir := opts.SaveTxtPath
		txtFile := filepath.Join(dir, basename+"-ascii-art.txt")
		var sb strings.Builder
		for y := 0; y < height; y++ {
			for x := 0; x < width; x++ {
				sb.WriteString(string(charMatrix[y][x]))
			}
			sb.WriteString("\n")
		}
		if err := os.WriteFile(txtFile, []byte(sb.String()), 0644); err != nil {
			return fmt.Errorf("can't save file: %v", err)
		}
		if opts.OnlySave {
			fmt.Printf("Saved %s\n", txtFile)
		}
	}

	if opts.SaveImgPath != "" {
		dir := opts.SaveImgPath
		imgFile := filepath.Join(dir, basename+"-ascii-art.png")

		ttfFont, err := font.LoadFont(opts.Font, opts.Braille)
		if err != nil {
			return err
		}

		outW := 10 + 14*width
		outH := 10 + 28*height
		outImg := image.NewRGBA(image.Rect(0, 0, outW, outH))

		bgR := uint8(opts.SaveBg[0])
		bgG := uint8(opts.SaveBg[1])
		bgB := uint8(opts.SaveBg[2])
		bgA := uint8(float64(opts.SaveBg[3]) * 255.0 / 100.0)
		bgColor := color.RGBA{R: bgR, G: bgG, B: bgB, A: bgA}

		for y := 0; y < outH; y++ {
			for x := 0; x < outW; x++ {
				outImg.SetRGBA(x, y, bgColor)
			}
		}

		for y := 0; y < height; y++ {
			for x := 0; x < width; x++ {
				r := charMatrix[y][x]
				cellX := 5 + x*14
				cellY := 5 + y*28

				var textColor color.RGBA
				if opts.Color {
					c := rgbMatrix[y][x]
					textColor = color.RGBA{R: c[0], G: c[1], B: c[2], A: 255}
				} else if opts.Grayscale {
					c := rgbMatrix[y][x]
					lum := uint8(math.Round(0.299*float64(c[0]) + 0.587*float64(c[1]) + 0.114*float64(c[2])))
					textColor = color.RGBA{R: lum, G: lum, B: lum, A: 255}
				} else {
					textColor = color.RGBA{R: uint8(opts.FontColor[0]), G: uint8(opts.FontColor[1]), B: uint8(opts.FontColor[2]), A: 255}
				}

				ttfFont.DrawRune(outImg, r, cellX, cellY, 14, 28, textColor)
			}
		}

		f, err := os.Create(imgFile)
		if err != nil {
			return fmt.Errorf("can't save file: %v", err)
		}
		if err := png.Encode(f, outImg); err != nil {
			f.Close()
			return fmt.Errorf("can't save file: %v", err)
		}
		f.Close()

		if opts.OnlySave {
			fmt.Printf("Saved %s\n", imgFile)
		}
	}

	return nil
}

var _ = time.Millisecond
EOF"}

