{"command":"cat <<'EOF' > /tmp/test_gamma_sweep.go
package main

import (
	"fmt"
	"image"
	_ "image/png"
	"math"
	"os"
	"os/exec"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/resize"
)

func ditherGammaExponent(img *image.RGBA, gamma float64) string {
	w, h := img.Bounds().Dx(), img.Bounds().Dy()

	gridR := make([][]float64, h)
	gridG := make([][]float64, h)
	gridB := make([][]float64, h)
	for y := 0; y < h; y++ {
		gridR[y] = make([]float64, w)
		gridG[y] = make([]float64, w)
		gridB[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			c := img.At(x, y)
			r, g, b, _ := c.RGBA()
			gridR[y][x] = math.Pow(float64(r)/65535.0, gamma)
			gridG[y][x] = math.Pow(float64(g)/65535.0, gamma)
			gridB[y][x] = math.Pow(float64(b)/65535.0, gamma)
		}
	}

	ditheredBits := make([][]bool, h)
	for y := 0; y < h; y++ {
		ditheredBits[y] = make([]bool, w)
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			r := gridR[y][x]
			g := gridG[y][x]
			b := gridB[y][x]

			distBlack := r*r + g*g + b*b
			dR := 1.0 - r
			dG := 1.0 - g
			dB := 1.0 - b
			distWhite := dR*dR + dG*dG + dB*dB

			var target float64
			if distWhite < distBlack {
				target = 1.0
				ditheredBits[y][x] = true
			} else {
				target = 0.0
				ditheredBits[y][x] = false
			}

			errR := r - target
			errG := g - target
			errB := b - target

			diffuse := func(nx, ny int, factor float64) {
				if nx >= 0 && nx < w && ny >= 0 && ny < h {
