{"command":"cat <<'EOF' > /tmp/test_dither_intdiv.go
package main

import (
	"fmt"
	"image"
	_ "image/png"
	"math"
	"os"
	"os/exec"
	"strings"

	"github.com/TheZoraiz/ascii-image-converter/resize"
)

func sRGBToLinear255(v float64) float64 {
	v /= 255.0
	if v <= 0.04045 {
		return (v / 12.92) * 255.0
	}
	return math.Pow((v+0.055)/1.055, 2.4) * 255.0
}

func ditherIntDiv(img *image.RGBA) string {
	w, h := img.Bounds().Dx(), img.Bounds().Dy()

	gray := make([][]float64, h)
	for y := 0; y < h; y++ {
		gray[y] = make([]float64, w)
		for x := 0; x < w; x++ {
			c := img.RGBAAt(x, y)
			r := sRGBToLinear255(float64(c.R))
			g := sRGBToLinear255(float64(c.G))
			b := sRGBToLinear255(float64(c.B))
			gray[y][x] = 0.299*r + 0.587*g + 0.114*b
		}
	}

	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			oldV := gray[y][x]
			newV := 0.0
			if oldV >= 128.0 {
				newV = 255.0
			}
			gray[y][x] = newV
			err := oldV - newV

			if x+1 < w { gray[y][x+1] += float64(int(err * 7)) / 16.0 }
			if y+1 < h {
				if x-1 >= 0 { gray[y+1][x-1] += float64(int(err * 3)) / 16.0 }
				gray[y+1][x] += float64(int(err * 5)) / 16.0
				if x+1 < w { gray[y+1][x+1] += float64(int(err * 1)) / 16.0 }
			}
		}
	}

	dotMap := [4][2]rune{
		{0x01, 0x08},
		{0x02, 0x10},
		{0x04, 0x20},
		{0x40, 0x80},
	}
	var sb strings.Builder
	for hy := 0; hy < h/4; hy++ {
		for wx := 0; wx < w/2; wx++ {
			var bitmask rune
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					px := wx*2 + dx
					py := hy*4 + dy
					if gray[py][px] >= 128.0 {
						bitmask |= dotMap[dy][dx]
					}
				}
			}
			sb.WriteRune(rune(0x2800 + bitmask))
		}
		sb.WriteString("\n")
	}
	return strings.TrimSpace(sb.String())
}

func main() {
	out, _ := exec.Command("./executable", "/tmp/gradient10.png", "-d", "10,10", "-b", "--dither").Output()
	orig := strings.TrimSpace(string(out))

	f, _ := os.Open("/tmp/gradient10.png")
	srcImg, _, _ := image.Decode(f)
	f.Close()

	img := resize.Resize(20, 40, srcImg)
	res := ditherIntDiv(img)

	fmt.Println("IntDiv Dither Match:", res == orig)
	if res == orig {
		fmt.Println("EXACT 100% MATCH SUCCESSFUL!")
	} else {
		fmt.Println("ORIGINAL:")
		fmt.Println(orig)
		fmt.Println("REBUILT:")
		fmt.Println(res)
	}
}
EOF
go run /tmp/test_dither_intdiv.go"}

